import math

def occam_bound(R, C, n, delta):
    arg = (C + math.log(1/delta)) / (2*n)
    return R + (math.sqrt(arg) if arg > 0 else 0.0)

def perturbed(R, C, L, rho, n, delta):
    return occam_bound(R + L*rho, C, n, delta)

R, C, L, rho, delta = 0.05, 8192*math.log(2), 1.6, 0.1, 0.05
floor = R + L*rho
for k in range(2, 10):
    n = 10**k
    b = perturbed(R, C, L, rho, n, delta)
    print(f'n={n:>12}  bound={b:.6f}  dist_to_floor={b-floor:.8f}')

import math
from dataclasses import dataclass

def perturbed(R, C, L, rho, n, delta):
    arg = (C + math.log(1/delta)) / (2*n)
    return (R + L*rho) + (math.sqrt(arg) if arg > 0 else 0.0)

@dataclass
class Net:
    params: int
    bits: int
    emp_risk: float

def bound(net: Net, L, rho, n, delta):
    return perturbed(net.emp_risk, net.bits*math.log(2), L, rho, n, delta)

n, delta, L, rho = 50_000, 0.05, 1.6, 0.1
tiny = Net(10_000, 4096, 0.05)
huge = Net(1_000_000_000, 4096, 0.05)
print('tiny:', bound(tiny, L, rho, n, delta))
print('huge:', bound(huge, L, rho, n, delta))  # identical

